DROP VIEW "public"."reach_invites";--> statement-breakpoint
ALTER TABLE "reach_messages" DROP CONSTRAINT "ck_reach_messages_state";--> statement-breakpoint
ALTER TABLE "reach_contacts" ADD COLUMN "fit" jsonb;--> statement-breakpoint
ALTER TABLE "reach_messages" ADD CONSTRAINT "ck_reach_messages_state" CHECK (("state")::text = ANY ((ARRAY['proposed'::character varying, 'queued'::character varying, 'sending'::character varying, 'sent'::character varying, 'failed'::character varying, 'unknown'::character varying, 'skipped'::character varying, 'received'::character varying])::text[]));--> statement-breakpoint
CREATE VIEW "public"."reach_invites" AS (SELECT m.id, m.contact_id, m.account_id, c.handle, c.url, c.name, c.headline, c.niche, c.person_id, c.company_id, c.found_in, c.fit, NULLIF(m.body, '') AS note, CASE WHEN c.connected_at IS NOT NULL THEN 'accepted' WHEN c.withdrawn_at IS NOT NULL THEN 'withdrawn' WHEN m.state = 'sent' AND c.state = 'enrolled' THEN 'pending' WHEN m.state = 'sent' THEN 'ended' WHEN m.state IN ('queued', 'sending') THEN 'queued' ELSE m.state END AS status, coalesce(m.state_reason, c.state_reason) AS state_reason, m.created_at AS queued_at, m.sent_at, c.connected_at, c.withdrawn_at FROM reach_messages m JOIN reach_contacts c ON c.id = m.contact_id WHERE m.kind = 'connect' AND m.direction = 'out');